  1→'use client';
  2→
  3→import { useState, useEffect, useRef, useCallback } from 'react';
  4→import { usePathname } from 'next/navigation';
  5→import Link from 'next/link';
  6→import dynamic from 'next/dynamic';
  7→
  8→const ChatBot = dynamic(() => import('./ChatBot').then(mod => ({ default: mod.ChatBot })), {
  9→  ssr: false,
 10→});
 11→
 12→const ToolsOverlay = dynamic(() => import('./ToolsOverlay').then(mod => ({ default: mod.ToolsOverlay })), {
 13→  ssr: false,
 14→});
 15→
 16→/**
 17→ * NAVIGATION - Sagmeister-informed sizing
 18→ *
 19→ * Typography hierarchy (responsive clamp):
 20→ * - Logo: 19px mobile → 22px desktop (uppercase, tracked)
 21→ * - Nav links: 18px mobile → 21px desktop (uppercase, tracked)
 22→ * - Generous letter-spacing creates presence
 23→ * - Medium weight (500) for refined look vs Sagmeister's bold (700)
 24→ */
 25→
 26→export function Navigation() {
 27→  const [isChatOpen, setIsChatOpen] = useState(false);
 28→  const [isMenuOpen, setIsMenuOpen] = useState(false);
 29→  const [isToolsOpen, setIsToolsOpen] = useState(false);
 30→  const [scrollProgress, setScrollProgress] = useState(0);
 31→  const pathname = usePathname();
 32→
 33→  // Double-click detection for chatbot icon Easter Egg
 34→  const clickCountRef = useRef(0);
 35→  const clickTimerRef = useRef<NodeJS.Timeout | null>(null);
 36→
 37→  // Double-click detection for chatbot icon
 38→  // Single click: open chatbot
 39→  // Double-click: reveal Tools & Downloads overlay (Easter Egg)
 40→  const handleChatbotClick = useCallback(() => {
 41→    clickCountRef.current++;
 42→
 43→    if (clickCountRef.current === 2) {
 44→      // Double-click detected - open Tools overlay (Easter Egg)
 45→      clickCountRef.current = 0;
 46→      if (clickTimerRef.current) {
 47→        clearTimeout(clickTimerRef.current);
 48→        clickTimerRef.current = null;
 49→      }
 50→      setIsToolsOpen(true);
 51→    } else {
 52→      // Wait for potential second click
 53→      clickTimerRef.current = setTimeout(() => {
 54→        if (clickCountRef.current === 1) {
 55→          // Single click - open chatbot normally
 56→          setIsChatOpen(true);
 57→        }
 58→        clickCountRef.current = 0;
 59→      }, 300);
 60→    }
 61→  }, []);
 62→
 63→  // Cleanup timer on unmount
 64→  useEffect(() => {
 65→    return () => {
 66→      if (clickTimerRef.current) {
 67→        clearTimeout(clickTimerRef.current);
 68→      }
 69→    };
 70→  }, []);
 71→
 72→  // Close menu when route changes
 73→  useEffect(() => {
 74→    setIsMenuOpen(false);
 75→  }, [pathname]);
 76→
 77→  // Focus trap: set inert on background content when mobile menu is open
 78→  useEffect(() => {
 79→    const mainContent = document.getElementById('main-content');
 80→    const footer = document.querySelector('footer');
 81→    if (isMenuOpen) {
 82→      mainContent?.setAttribute('inert', '');
 83→      footer?.setAttribute('inert', '');
 84→    } else {
 85→      mainContent?.removeAttribute('inert');
 86→      footer?.removeAttribute('inert');
 87→    }
 88→    return () => {
 89→      mainContent?.removeAttribute('inert');
 90→      footer?.removeAttribute('inert');
 91→    };
 92→  }, [isMenuOpen]);
 93→
 94→  const isHomePage = pathname === '/';
 95→  const isProjectPage = pathname?.startsWith('/projects/');
 96→  // Pages with hero reels need transparent navigation
 97→  const hasHeroReel = isHomePage || isProjectPage;
 98→
 99→  // Active state helper - for aria-current accessibility only (no visual change)
100→  const isActive = (href: string) => {
101→    if (href === '/') return isHomePage || isProjectPage;
102→    return pathname?.startsWith(href);
103→  };
104→
105→  // Track scroll for background opacity - MUST match hero reel fade calculations exactly
106→  // Navigation background fades in as hero video fades out (synchronized)
107→  useEffect(() => {
108→    if (!hasHeroReel) return;
109→
110→    const handleScroll = () => {
111→      const scrollY = window.scrollY;
112→      const viewportHeight = window.innerHeight;
113→      const heroHeight = viewportHeight * 0.7;
114→
115→      let fadeStartScroll: number;
116→      let fadeRange: number;
117→
118→      if (isProjectPage) {
119→        // ProjectHeroReel calculation: starts at 30% of hero height
120→        fadeStartScroll = heroHeight * 0.3;
121→        fadeRange = 300;
122→      } else {
123→        // Homepage HeroReel calculation: tied to intro text position
124→        const introPadding = 160;
125→        const textStartPosition = heroHeight + introPadding;
126→        const oneThirdViewport = viewportHeight / 3;
127→        fadeStartScroll = textStartPosition - oneThirdViewport;
128→        fadeRange = 200;
129→      }
130→
131→      const progress = Math.max(0, Math.min((scrollY - fadeStartScroll) / fadeRange, 1));
132→      setScrollProgress(progress);
133→    };
134→
135→    // Run immediately to sync initial state with hero reel
136→    handleScroll();
137→
138→    window.addEventListener('scroll', handleScroll, { passive: true });
139→    return () => window.removeEventListener('scroll', handleScroll);
140→  }, [hasHeroReel, isProjectPage]);
141→
142→  // Navigation text color - uses design system variable
143→  const textColor = 'var(--text-primary)';
144→
145→  return (
146→    <>
147→    <nav
148→      className="fixed top-0 left-0 right-0 w-full"
149→      style={{
150→        // Hero reel pages: transparent → solid on scroll (NO CSS transition - scroll IS the animation)
151→        // Other pages: solid background
152→        backgroundColor: hasHeroReel
153→          ? `rgba(20, 20, 20, ${scrollProgress})`
154→          : '#141414',
155→        zIndex: 100,
156→        // Exclude from page transition scale - nav should only fade, not move
157→        viewTransitionName: 'navigation'
158→      }}
159→    >
160→      {/* Pentagram-style: fixed padding, not dramatic scaling */}
161→      <div
162→        className="mx-auto"
163→        style={{
164→          maxWidth: 'var(--max-content-width)',
165→          paddingTop: '28px',
166→          paddingBottom: '20px'
167→        }}
168→      >
169→        {/* Top row: Name and Nav - baseline aligned */}
170→        <div
171→          className="flex items-baseline justify-between"
172→          style={{
173→            paddingLeft: 'var(--side-padding)',
174→            paddingRight: 'var(--side-padding)'
175→          }}
176→        >
177→          {/* Logo - uses <a> intentionally (not <Link>) so homepage navigation
178→              does a full reload, avoiding white flash from Vimeo iframe reinit
179→              during view transitions */}
180→          <a
181→            href="/"
182→            className="nav-link transition-opacity duration-400"
183→            style={{
184→              color: textColor,
185→              fontFamily: 'var(--font-display)',
186→              fontWeight: 500,
187→              letterSpacing: '0.16em',
188→              fontSize: 'clamp(19px, 0.5vw + 15px, 22px)',
189→              textTransform: 'uppercase'
190→            }}
191→          >
192→            Joseph Ibrahim
193→          </a>
194→
195→          {/* Desktop Navigation - responsive scaling maintains spacing ratio */}
196→          <div className="hidden md:flex items-baseline" style={{ gap: 'clamp(24px, 2.5vw, 36px)' }}>
197→            <ul className="flex items-baseline" style={{ gap: 'clamp(20px, 2vw, 28px)' }}>
198→              <li>
199→                <Link
200→                  href="/"
201→                  className="nav-link nav-item-shift transition-opacity duration-400"
202→                  style={{
203→                    color: textColor,
204→                    fontFamily: 'var(--font-display)',
205→                    fontWeight: 500,
206→                    letterSpacing: '0.10em',
207→                    fontSize: 'clamp(18px, 0.5vw + 14px, 21px)',
208→                    textTransform: 'uppercase'
209→                  }}
210→                  aria-current={isActive('/') ? 'page' : undefined}
211→                >
212→                  Work
213→                </Link>
214→              </li>
215→              {/* GEN AI - temporarily hidden, page still accessible at /gen-ai */}
216→              <li>
217→                <Link
218→                  href="/photo"
219→                  className="nav-link nav-item-shift transition-opacity duration-400"
220→                  style={{
221→                    color: textColor,
222→                    fontFamily: 'var(--font-display)',
223→                    fontWeight: 500,
224→                    letterSpacing: '0.10em',
225→                    fontSize: 'clamp(18px, 0.5vw + 14px, 21px)',
226→                    textTransform: 'uppercase'
227→                  }}
228→                  aria-current={isActive('/photo') ? 'page' : undefined}
229→                >
230→                  Photo
231→                </Link>
232→              </li>
233→              <li>
234→                <Link
235→                  href="/process"
236→                  className="nav-link nav-item-shift transition-opacity duration-400"
237→                  style={{
238→                    color: textColor,
239→                    fontFamily: 'var(--font-display)',
240→                    fontWeight: 500,
241→                    letterSpacing: '0.10em',
242→                    fontSize: 'clamp(18px, 0.5vw + 14px, 21px)',
243→                    textTransform: 'uppercase'
244→                  }}
245→                  aria-current={isActive('/process') ? 'page' : undefined}
246→                >
247→                  Process
248→                </Link>
249→              </li>
250→              <li>
251→                <Link
252→                  href="/info"
253→                  className="nav-link nav-item-shift transition-opacity duration-400"
254→                  style={{
255→                    color: textColor,
256→                    fontFamily: 'var(--font-display)',
257→                    fontWeight: 500,
258→                    letterSpacing: '0.10em',
259→                    fontSize: 'clamp(18px, 0.5vw + 14px, 21px)',
260→                    textTransform: 'uppercase'
261→                  }}
262→                  aria-current={isActive('/info') ? 'page' : undefined}
263→                >
264→                  About
265→                </Link>
266→              </li>
267→            </ul>
268→
269→            {/* Chat bubble icon - aligned to top of nav text */}
270→            {/* Single-click: open chatbot | Double-click: reveal Tools overlay (Easter Egg) */}
271→            {/* Matches nav-link hover behavior exactly (dims to 40% on hover) */}
272→            <button
273→              onClick={handleChatbotClick}
274→              className="nav-link nav-item-shift transition-opacity duration-400"
275→              aria-label="Ask about Joe"
276→              style={{
277→                alignSelf: 'flex-start',
278→                marginTop: '5px',
279→                background: 'transparent',
280→                border: 'none',
281→                padding: 0,
282→                cursor: 'pointer'
283→              }}
284→            >
285→              <svg
286→                viewBox="0 0 24 24"
287→                style={{
288→                  width: '17px',
289→                  height: '17px'
290→                }}
291→              >
292→                <path
293→                  d="M20 2H4C2.9 2 2 2.9 2 4v12c0 1.1.9 2 2 2h2v4l5-4h9c1.1 0 2-.9 2-2V4c0-1.1-.9-2-2-2z"
294→                  fill={textColor}
295→                />
296→              </svg>
297→            </button>
298→          </div>
299→
300→          {/* Mobile: Chat + Hamburger - 44px min touch targets */}
301→          {/* Single-click: open chatbot | Double-click: reveal Tools overlay (Easter Egg) */}
302→          <div className="flex md:hidden items-center gap-3">
303→            <button
304→              onClick={handleChatbotClick}
305→              className="nav-link nav-item-shift transition-opacity duration-400"
306→              aria-label="Ask about Joe"
307→              style={{
308→                minWidth: '44px',
309→                minHeight: '44px',
310→                display: 'flex',
311→                alignItems: 'center',
312→                justifyContent: 'center',
313→                background: 'transparent',
314→                border: 'none',
315→                padding: '12px',
316→                margin: '-8px',
317→                cursor: 'pointer'
318→              }}
319→            >
320→              <svg
321→                width="20"
322→                height="20"
323→                viewBox="0 0 24 24"
324→              >
325→                <path
326→                  d="M20 2H4C2.9 2 2 2.9 2 4v12c0 1.1.9 2 2 2h2v4l5-4h9c1.1 0 2-.9 2-2V4c0-1.1-.9-2-2-2z"
327→                  fill={textColor}
328→                />
329→              </svg>
330→            </button>
331→
332→            {/* Hamburger - 44px min touch target */}
333→            <button
334→              onClick={() => setIsMenuOpen(true)}
335→              className="transition-opacity duration-400 hover:opacity-60 p-3 -m-2"
336→              aria-label="Open menu"
337→              style={{ minWidth: '44px', minHeight: '44px', display: 'flex', alignItems: 'center', justifyContent: 'center' }}
338→            >
339→              <svg
