 21→
 22→  /* Fibonacci spacing scale (each × φ ≈ next) */
 23→  --space-xs: 21px;    /* Fibonacci */
 24→  --space-sm: 34px;    /* 21 × 1.618 ≈ 34 */
 25→  --space-md: 55px;    /* 34 × 1.618 ≈ 55 */
 26→  --space-lg: 89px;    /* 55 × 1.618 ≈ 89 */
 27→  --space-xl: 144px;   /* 89 × 1.618 ≈ 144 */
 28→  --space-2xl: 233px;  /* 144 × 1.618 ≈ 233 */
 29→  --space-section: 120px; /* Editorial section gap */
 30→
 31→  /* Typography - Helvetica Neue alternative */
 32→  /* Inter: neo-grotesque sans-serif, clean, neutral, screen-optimized */
 33→  --font-display: var(--font-inter), 'Inter', sans-serif;
 34→  --font-body: var(--font-inter), 'Inter', sans-serif;
 35→
 36→  /* Color palette - Dark with warm accent */
 37→  --background: #141414;
 38→  --foreground: #b8b8b8;
 39→  --text-primary: #e8e8e8;
