 66→  --grey-500: #7a7a7a;  /* Medium grey — DESCRIPTIONS */
 67→  --grey-600: #6a6a6a;  /* Muted text (= --text-muted) */
 68→  --grey-700: #5a5a5a;  /* Dim text (= --text-dim) — METADATA */
 69→  --grey-800: #3a3a3a;  /* Separator dots */
 70→  --grey-900: #2a2a2a;  /* Borders (= --border) */
 71→  --grey-750: #4a4a4a;  /* Subtle labels, metadata */
