 31→export function HeroReel({ videoId, videoHash, startTime = 0 }: HeroReelProps) {
 32→  const containerRef = useRef<HTMLDivElement>(null);
 33→  const playerRef = useRef<Player | null>(null);
 34→  const isReadyRef = useRef(false);
 35→  const scrolledDownRef = useRef(false);
 36→
 37→  const [scrollProgress, setScrollProgress] = useState(0);
 38→  const [heroRevealed, setHeroRevealed] = useState(false);
 39→  const [videoPlaying, setVideoPlaying] = useState(false);
 40→  const [isMuted, setIsMuted] = useState(true);
 41→
 42→  const { isMobile, isReady: isMobileReady } = useIsMobile();
 43→  const prefersReducedMotion = usePrefersReducedMotion();
 44→
 45→  // Hero height based on device
 46→  const heroHeight = isMobile ? '50vh' : '70vh';
 47→
 48→  // Clean destroy of player instance
 49→  const destroyPlayer = useCallback(() => {
 50→    if (playerRef.current) {
 51→      try {
 52→        playerRef.current.destroy();
 53→      } catch {
 54→        // Player may already be destroyed
 55→      }
 56→      playerRef.current = null;
 57→    }
 58→    isReadyRef.current = false;
 59→  }, []);
 60→
 61→  // Reveal hero after navigation settles (creates cinematic entrance sequence)
 62→  useEffect(() => {
 63→    const revealTimer = setTimeout(() => setHeroRevealed(true), 400);
 64→    return () => clearTimeout(revealTimer);
 65→  }, []);
 66→
 67→  // Initialize Vimeo player with autoplay (desktop only)
 68→  useEffect(() => {
 69→    // Wait for mobile detection to complete before deciding
 70→    if (!isMobileReady) return;
 71→
 72→    // Skip player initialization on mobile - use static thumbnail instead
 73→    if (isMobile) return;
 74→
 75→    if (!containerRef.current) return;
 76→
 77→    const baseConfig = {
 78→      muted: true,
 79→      loop: true,
 80→      autoplay: true,
 81→      controls: false,
 82→      background: true,
 83→      responsive: true,
 84→      title: false,
 85→      byline: false,
 86→      portrait: false,
 87→      dnt: true,
 88→      playsinline: true,
 89→      quality: 'auto',
 90→      speed: true,
 91→      transparent: false, // Request dark player background from Vimeo
 92→    };
 93→
 94→    const baseUrl = videoHash
 95→      ? `https://vimeo.com/${videoId}/${videoHash}`
 96→      : `https://vimeo.com/${videoId}`;
 97→    const urlWithTime = startTime > 0 ? `${baseUrl}#t=${startTime}s` : baseUrl;
 98→
 99→    let isMounted = true;
100→
101→    const initPlayer = async () => {
102→      try {
103→        const VimeoPlayer = await loadVimeoPlayer();
104→        if (!isMounted || !containerRef.current) return;
105→
106→        playerRef.current = new VimeoPlayer(containerRef.current!, {
107→          url: urlWithTime as `https://vimeo.com/${string}`,
108→          ...baseConfig
109→        });
110→
111→        // Race between ready() and timeout
112→        const readyPromise = playerRef.current.ready();
113→        const timeoutPromise = new Promise<never>((_, reject) => {
114→          setTimeout(() => reject(new Error('HeroReel initialization timeout')), INIT_TIMEOUT_MS);
115→        });
116→
117→        await Promise.race([readyPromise, timeoutPromise]);
118→
119→        if (!isMounted) {
120→          destroyPlayer();
121→          return;
122→        }
123→
124→        isReadyRef.current = true;
125→
126→        // Add error event listener for runtime failures
127→        playerRef.current.on('error', (error) => {
128→          console.error('HeroReel: Player error', videoId, error);
129→        });
130→
131→        // Wait for video to actually start rendering frames before revealing.
132→        // 'bufferend' fires when enough data is buffered to play without interruption.
133→        // 'playing' fires when playback actually begins after buffering.
134→        // Ultimate fallback: reveal after INIT_TIMEOUT_MS regardless.
135→        const revealOnce = () => {
136→          if (isMounted) setVideoPlaying(true);
137→        };
138→        playerRef.current.on('bufferend', revealOnce);
139→        playerRef.current.on('playing', revealOnce);
140→
141→        // Start playback (may already be playing via background autoplay)
142→        await playerRef.current.play().catch(() => {});
143→      } catch (err) {
144→        console.error('HeroReel: Player init failed', videoId, err);
145→        destroyPlayer();
146→      }
147→    };
148→
149→    initPlayer();
150→
151→    return () => {
152→      isMounted = false;
153→      destroyPlayer();
154→    };
155→  }, [videoId, videoHash, startTime, destroyPlayer, isMobile, isMobileReady]);
156→
157→  // Track scroll for fade and pause/resume
158→  useEffect(() => {
159→    const handleScroll = () => {
160→      const scrollY = window.scrollY;
161→      const viewportHeight = window.innerHeight;
162→      // Use appropriate hero height multiplier based on device
163→      const heroHeightValue = viewportHeight * (isMobile ? 0.5 : 0.7);
164→      const introPadding = 160;
165→      const textStartPosition = heroHeightValue + introPadding;
166→      const oneThirdViewport = viewportHeight / 3;
167→      const fadeStartScroll = textStartPosition - oneThirdViewport;
168→
169→      const fadeRange = 200;
170→      const progress = Math.max(0, Math.min((scrollY - fadeStartScroll) / fadeRange, 1));
171→      setScrollProgress(progress);
172→
173→      // Pause/resume with ref tracking for consistency (desktop only)
174→      if (!isMobile) {
175→        const hasScrolledDown = scrollY > 10;
176→
177→        if (hasScrolledDown && !scrolledDownRef.current) {
178→          scrolledDownRef.current = true;
179→          if (playerRef.current && isReadyRef.current) {
180→            playerRef.current.pause().catch(() => {});
181→          }
182→        } else if (!hasScrolledDown && scrolledDownRef.current) {
183→          scrolledDownRef.current = false;
184→          if (playerRef.current && isReadyRef.current) {
185→            playerRef.current.play().catch(() => {});
186→          }
187→        }
188→      }
189→    };
190→
191→    // Run immediately to sync initial state
192→    handleScroll();
193→
194→    window.addEventListener('scroll', handleScroll, { passive: true });
195→    return () => window.removeEventListener('scroll', handleScroll);
196→  }, [isMobile]);
197→
198→  const toggleMute = useCallback(() => {
199→    if (playerRef.current && isReadyRef.current) {
200→      const newMuted = !isMuted;
201→      playerRef.current.setVolume(newMuted ? 0 : 0.5).catch(() => {});
202→      setIsMuted(newMuted);
203→    }
204→  }, [isMuted]);
205→
206→  const scrollOpacity = 1 - scrollProgress;
207→  const heroOpacity = heroRevealed ? scrollOpacity : 0;
208→  const heroScale = heroRevealed ? 1 : 1.02;
209→  const transitionDuration = prefersReducedMotion ? '0ms' : '1.2s';
210→  const transitionEasing = 'cubic-bezier(0.16, 1, 0.3, 1)';
211→
212→  // Transition strategy: opacity only animates during initial reveal, then becomes instant for scroll
213→  // This ensures scroll-driven fade is perfectly synchronized with navigation
214→  const heroTransition = heroRevealed
215→    ? `transform ${transitionDuration} ${transitionEasing}, filter ${transitionDuration} ${transitionEasing}`
216→    : `opacity ${transitionDuration} ${transitionEasing}, transform ${transitionDuration} ${transitionEasing}, filter ${transitionDuration} ${transitionEasing}`;
217→
218→  return (
219→    <div
220→      className="fixed top-0 left-0 right-0 w-full overflow-hidden"
221→      style={{
222→        height: heroHeight,
223→        zIndex: 0,
224→        backgroundColor: '#141414',
225→        // Exclude from view transition snapshot — prevents white flash
226→        // when Vimeo iframe is destroyed/recreated during page transitions
227→        viewTransitionName: 'hero-reel',
228→      }}
229→    >
230→      <div
231→        style={{
232→          width: '100%',
233→          height: '100%',
234→          opacity: heroOpacity,
235→          transform: `scale(${heroScale})`,
236→          filter: heroRevealed ? 'saturate(1) brightness(1)' : 'saturate(0.3) brightness(0.6)',
237→          transition: heroTransition,
238→          transformOrigin: 'center center',
239→          willChange: heroRevealed ? 'auto' : 'opacity, transform, filter'
240→        }}
241→      >
242→        {!isMobile && (
243→          // Desktop: Vimeo player container (behind thumbnail until video plays)
244→          <div
245→            ref={containerRef}
246→            className="absolute inset-0 w-full h-full"
247→            style={{
248→              backgroundColor: '#141414',
249→              zIndex: 0
250→            }}
251→          />
252→        )}
253→        {/* Dark overlay - sits ABOVE iframe, matches site background until video plays.
254→            Video emerges seamlessly from the page background. */}
255→        <div
256→          className="absolute inset-0 w-full h-full"
257→          style={{
258→            backgroundColor: '#141414',
259→            zIndex: 1,
260→            opacity: videoPlaying ? 0 : 1,
261→            transition: 'opacity 0.4s ease-out',
262→            pointerEvents: 'none'
263→          }}
264→        />
265→      </div>
266→
267→      {/* Sound toggle - desktop only, appears after video starts playing */}
268→      {!isMobile && videoPlaying && (
269→        <button
270→          onClick={toggleMute}
271→          aria-label={isMuted ? 'Unmute video' : 'Mute video'}
272→          className="transition-opacity duration-300 hover:opacity-100"
273→          style={{
274→            position: 'absolute',
275→            bottom: '20px',
276→            right: '20px',
277→            zIndex: 2,
278→            background: 'rgba(20, 20, 20, 0.6)',
279→            border: 'none',
280→            borderRadius: '50%',
281→            width: '36px',
282→            height: '36px',
283→            display: 'flex',
284→            alignItems: 'center',
285→            justifyContent: 'center',
286→            cursor: 'pointer',
287→            opacity: 0.5,
288→            backdropFilter: 'blur(4px)'
289→          }}
290→        >
291→          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="var(--text-dim)" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
292→            {isMuted ? (
293→              <>
294→                <polygon points="11 5 6 9 2 9 2 15 6 15 11 19 11 5" fill="var(--text-dim)" />
295→                <line x1="23" y1="9" x2="17" y2="15" />
296→                <line x1="17" y1="9" x2="23" y2="15" />
297→              </>
298→            ) : (
299→              <>
300→                <polygon points="11 5 6 9 2 9 2 15 6 15 11 19 11 5" fill="var(--text-dim)" />
301→                <path d="M15.54 8.46a5 5 0 010 7.07" />
302→                <path d="M19.07 4.93a10 10 0 010 14.14" />
303→              </>
304→            )}
305→          </svg>
306→        </button>
307→      )}
308→    </div>
